const fs = require("fs");
const path = require("path");
const { getWorktreeContext } = require("./worktree-context");

const root = process.cwd();
const envExamplePath = path.join(root, "env.development.example");
const envDevelopmentPath = path.join(root, ".env.development");
const envWorktreePath = path.join(root, ".env.worktree");

function createWorktreeEnv() {
	const context = getWorktreeContext(root);
	const content = [
		`# Generated by scripts/bootstrap-worktree-env.js for ${context.worktreeName}`,
		`COMPOSE_PROJECT_NAME=${context.composeProjectName}`,
		`PORT=${context.appPort}`,
		`DB_PORT=${context.dbPort}`,
		`REDIS_PORT=${context.redisPort}`,
		`GRAFANA_PORT=${context.grafanaPort}`,
		`LOKI_PORT=${context.lokiPort}`,
		`TEMPO_PORT=${context.tempoPort}`,
		`OTLP_GRPC_PORT=${context.otlpGrpcPort}`,
		`OTLP_HTTP_PORT=${context.otlpHttpPort}`,
		`PROMETHEUS_PORT=${context.prometheusPort}`,
		`OTEL_SERVICE_NAME=${context.otelServiceName}`,
		"OTEL_ENABLED=false",
		`OTEL_EXPORTER_OTLP_ENDPOINT=http://127.0.0.1:${context.otlpHttpPort}`,
		"LOKI_ENABLED=false",
		`LOKI_URL=http://127.0.0.1:${context.lokiPort}`,
		`PROMETHEUS_BASE_URL=http://127.0.0.1:${context.prometheusPort}`,
		`TEMPO_BASE_URL=http://127.0.0.1:${context.tempoPort}`,
		`GRAFANA_BASE_URL=http://127.0.0.1:${context.grafanaPort}`,
		"SMOKE_STARTUP_BUDGET_MS=2000",
		"",
	].join("\n");

	fs.writeFileSync(envWorktreePath, content);
}

if (!fs.existsSync(envDevelopmentPath) && fs.existsSync(envExamplePath)) {
	fs.copyFileSync(envExamplePath, envDevelopmentPath);
	console.log("Created .env.development from env.development.example");
}

if (!fs.existsSync(envWorktreePath)) {
	createWorktreeEnv();
	console.log("Created .env.worktree with deterministic worktree-local stack defaults");
}
